file-transfers.snippet:
// Client upload
const file = input.files[0];
const buffer = await file.arrayBuffer();
await api.files.upload({ name: file.name, data: buffer });

// Server receive
export async function upload({ name, data }) {
  const buffer = Buffer.from(data);
  await fs.writeFile(`./uploads/${name}`, buffer);
  return { size: buffer.length };
}

connection-states.snippet:
api.onStateChange((state) => {
  switch (state) {
    case 'connected':
      showOnlineUI();
      break;
    case 'connecting':
      showReconnectingSpinner();
      break;
    case 'disconnected':
      showOfflineUI();
      break;
  }
});

